bool iconBitmap(const char* name, const uint8_t*& out) {
  if (!name) return false;
  for (const IconEntry& e : kIcons) {
    if (strcmp(e.name, name) == 0) {
      out = e.bits;
      return true;
    }
  }
  return false;
}

